package com.centralplay.app.ui;
import android.app.*;import android.content.*;import android.content.res.Configuration;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.recyclerview.widget.*;import com.centralplay.app.R;import com.centralplay.app.data.*;import com.centralplay.app.model.*;import com.google.gson.Gson;import java.text.DateFormat;import java.util.*;
public class ContentListFragment extends Fragment implements Searchable{private String mode="live",query="";private ContentAdapter adapter;private TextView empty;private Catalog catalog;public static ContentListFragment newInstance(String mode){ContentListFragment f=new ContentListFragment();Bundle b=new Bundle();b.putString("mode",mode);f.setArguments(b);return f;}public ContentListFragment(){super(R.layout.fragment_content_list);}@Override public void onCreate(Bundle b){super.onCreate(b);if(getArguments()!=null)mode=getArguments().getString("mode","live");}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle b){RecyclerView rv=v.findViewById(R.id.recycler);empty=v.findViewById(R.id.empty);rv.setLayoutManager(new GridLayoutManager(requireContext(),calculateColumns()));adapter=new ContentAdapter(requireContext(),new ContentAdapter.Listener(){public void onClick(ContentAdapter.Row row){open(row);}public void onLongClick(ContentAdapter.Row row){showInfo(row);}});rv.setAdapter(adapter);reload();}@Override public void onResume(){super.onResume();reload();}public void reload(){if(adapter==null||getContext()==null)return;catalog=CatalogRepository.get(requireContext()).getCachedCatalog();List<ContentAdapter.Row> rows=new ArrayList<>();boolean adult=Prefs.adultEnabled(requireContext());if("series".equals(mode)){for(SeriesEntry s:catalog.series)if(adult||!s.adult)rows.add(ContentAdapter.Row.series(s));}else{List<MediaEntry> src;if("movie".equals(mode))src=catalog.movies;else if("favorites".equals(mode)){src=new ArrayList<>();src.addAll(catalog.live);src.addAll(catalog.movies);for(SeriesEntry s:catalog.series)if(FavoritesStore.contains(requireContext(),s.id)&&(adult||!s.adult))rows.add(ContentAdapter.Row.series(s));}else src=catalog.live;for(MediaEntry m:src){if(!(adult||!m.adult))continue;if("favorites".equals(mode)&&!FavoritesStore.contains(requireContext(),m.id))continue;rows.add(ContentAdapter.Row.media(m));}}adapter.setRows(rows,query);empty.setVisibility(adapter.getItemCount()==0?View.VISIBLE:View.GONE);}@Override public void setQuery(String q){query=q==null?"":q;reload();}private void open(ContentAdapter.Row row){if(row.adult())promptPin(()->openNow(row));else openNow(row);}private void openNow(ContentAdapter.Row row){Gson g=new Gson();if(row.series!=null){Intent i=new Intent(requireContext(),SeriesDetailActivity.class);i.putExtra("series",g.toJson(row.series));startActivity(i);}else{Intent i=new Intent(requireContext(),PlayerActivity.class);i.putExtra("media",g.toJson(row.media));startActivity(i);}}private void promptPin(Runnable ok){String expected=Prefs.pin(requireContext());if(expected.trim().isEmpty()){new AlertDialog.Builder(requireContext()).setTitle("Control parental").setMessage("Configurá un PIN parental en Ajustes para abrir este contenido.").setPositiveButton("OK",null).show();return;}EditText input=new EditText(requireContext());input.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);input.setHint("PIN");new AlertDialog.Builder(requireContext()).setTitle("PIN parental").setView(input).setPositiveButton("Abrir",(d,w)->{String entered=input.getText()==null?"":input.getText().toString();if(expected.equals(entered))ok.run();else Toast.makeText(requireContext(),"PIN incorrecto",Toast.LENGTH_SHORT).show();}).setNegativeButton("Cancelar",null).show();}private void showInfo(ContentAdapter.Row row){String text;if(row.series!=null)text=row.series.description;else if("live".equals(row.media.type))text=epgText(row.media);else text=row.media.description;if(text==null||text.trim().isEmpty())text="Sin información adicional";new AlertDialog.Builder(requireContext()).setTitle(row.title()).setMessage(text).setPositiveButton("OK",null).show();}private String epgText(MediaEntry channel){StringBuilder s=new StringBuilder();if(channel.nowTitle!=null&&!channel.nowTitle.trim().isEmpty())s.append("Ahora: ").append(channel.nowTitle).append("\n");if(channel.nextTitle!=null&&!channel.nextTitle.trim().isEmpty())s.append("Después: ").append(channel.nextTitle).append("\n");if(catalog!=null&&catalog.epg!=null&&channel.tvgId!=null&&!channel.tvgId.trim().isEmpty()){DateFormat f=DateFormat.getTimeInstance(DateFormat.SHORT);int shown=0;for(EpgEvent e:catalog.epg){if(!channel.tvgId.equals(e.channelId)||e.stopMs<System.currentTimeMillis())continue;if(shown==0)s.append("\nGuía:\n");s.append(f.format(new Date(e.startMs))).append("  ").append(e.title).append("\n");if(++shown>=6)break;}}if(s.length()==0&&channel.description!=null)s.append(channel.description);return s.toString().trim();}private int calculateColumns(){Context c=requireContext();UiModeManager ui=(UiModeManager)c.getSystemService(Context.UI_MODE_SERVICE);if(ui!=null&&ui.getCurrentModeType()==Configuration.UI_MODE_TYPE_TELEVISION)return 5;return getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE?4:2;}}
